publish_with_retries:
(async function(local,remote,message){
const core=eval(load("PathPubCore"));
for(let attempt=0;attempt<=3;attempt++){
 try { return await core(local,remote,message); }
 catch(error){
  const note=String(error);
  if(/REMOTE_VERIFY_FAILED|LOCAL_PUBLICATION_GATE_FAILED|HASH_MISMATCH|FROZEN_ENGINE_DRIFT|EXTERNAL_CODE_DRIFT/.test(note))throw error;
  const transient=/RemoteProtocolError|Server disconnected|timed out|ConnectionError|ECONNRESET|HTTP.?50[234]|network.*failed|connection.*(closed|reset)/i.test(note);
  if(!transient)throw error;
  notify("일시적 GitHub 통신 오류: 원격 반영 여부를 먼저 확인합니다. 계산은 반복하지 않습니다.");
  const pending=load("PathCreatedCommit");
  if(pending?.local===local){
    const nr=async c=>{const r=await tools.mcp__node_repl__js({code:c,title:"불명확한 게시의 원격 반영 확인",timeout_ms:60000});if(r.isError)throw Error(JSON.stringify(r));return JSON.parse(r.content[0].text);};
    const f=await nr("nodeRepl.write(JSON.stringify(await exf('C:/Program Files/Git/cmd/git.exe',['-C',checkout,'fetch','origin','main'],55000)))");
    if(f.code!==0)throw Error("AMBIGUOUS_PUBLICATION_FETCH_BLOCKED");
    const a=await nr("nodeRepl.write(JSON.stringify(await exf('C:/Program Files/Git/cmd/git.exe',['-C',checkout,'merge-base','--is-ancestor',"+JSON.stringify(pending.commit)+",'origin/main'],20000)))");
    if(a.code===0)return await eval(load("PathRemoteVerify"))(local,remote,pending.commit);
    if(a.code!==1)throw Error("AMBIGUOUS_PUBLICATION_ANCESTRY_BLOCKED");
  }
  if(attempt===3)throw Error("PUBLICATION_TRANSIENT_RETRIES_EXHAUSTED "+note.slice(0,500));
  notify("동일 게시물만 재시도 "+(attempt+1)+"/3 — 신규 계산 없음");
 }
}
})

